set-variable.value:
#[[
  {file: "refund-policy.txt", domain: "order-management", documentType: "policy", version: "2026"},
  {file: "shipping-policy.txt", domain: "order-management", documentType: "policy", version: "2026"},
  {file: "cancellation-policy.txt", domain: "order-management", documentType: "policy", version: "2026"}
]]

ee:message.ee:set-payload:
%dw 2.0
output application/json
var size = vars.chunkSize as Number
var step = size - (vars.overlap as Number)
var text = vars.text as String
var n = if (sizeOf(text) <= size) 1 else ceil((sizeOf(text) - size) / step) + 1
// Snap raw character-count chunk boundaries out to the nearest whitespace,
// so a chunk never starts or ends mid-word (e.g. "an no longer be cancelled"
// instead of "...order can no longer be cancelled") - verified live that a
// mid-word-truncated chunk confused the downstream LLM into wrong/refused
// answers even though the full sentence was present one word earlier.
fun snapStart(pos: Number): Number =
  if (pos <= 0) 0
  else if ((text[(pos - 1) to (pos - 1)]) matches /\s/) pos
  else snapStart(pos - 1)
fun snapEnd(pos: Number): Number =
  if (pos >= sizeOf(text)) sizeOf(text)
  else if ((text[pos to pos]) matches /\s/) pos
  else snapEnd(pos + 1)
---
(0 to n - 1) map ((i) -> do {
  var rawStart = i * step
  var rawEnd = min([i * step + size, sizeOf(text)])
  var s = if (rawStart <= 0) 0 else snapStart(rawStart)
  var e = if (rawEnd >= sizeOf(text)) sizeOf(text) else snapEnd(rawEnd)
  ---
  trim(text[s to e - 1])
})

http:request.http:body:
#[output application/json
---
{
  model: "openai/gpt-oss-120b",
  messages: [
    {
      role: "system",
      content: "Answer the question using ONLY the provided context. Always explain your reasoning in full sentences using the context - never answer with just yes or no. If the context does not contain the answer, say exactly: I do not know."
    },
    {
      role: "user",
      content: "Context:\n" ++ (vars.retrievedChunks map $.text joinBy "\n\n") ++ "\n\nQuestion: " ++ vars.question
    }
  ],
  stream: false
}]
